import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import MiniCalendar from "../components/MiniCalendar";
import { useAuth } from "../context/AuthContext";
import "./Dashboard.css";

const QUICK_ACTIONS = [
  { to: "/card", label: "Student Card", icon: "🪪" },
  { to: "/wallet", label: "Wallet", icon: "👛" },
  { to: "/map", label: "Maps", icon: "🗺️" },
];

const TODAY_SCHEDULE = [
  { time: "09:00", title: "Computer Science — Lecture Hall A" },
  { time: "11:00", title: "Mathematics — Lecture Hall B" },
  { time: "14:00", title: "Study group — Library, Room 3" },
];

const ANNOUNCEMENTS = [
  { title: "WSU re-branding to UEC", date: "15 March 2026" },
  { title: "Library extended hours during exams", date: "10 March 2026" },
  { title: "Gym subscription renewals open", date: "02 March 2026" },
];

export default function Dashboard() {
  const { user, isGuest } = useAuth();
  const navigate = useNavigate();
  const [search, setSearch] = useState("");
  const [selectedDate, setSelectedDate] = useState(new Date());

  function handleSearch(e) {
    e.preventDefault();
    if (search.trim()) navigate(`/services?q=${encodeURIComponent(search.trim())}`);
  }

  return (
    <div>
      <Navbar />
      <div className="page-shell">
        <div className="dash-welcome">
          <div>
            <h2>Welcome back, <b>{isGuest ? "Guest" : user?.fullName?.split(" ")[0] || "Student"}</b></h2>
            <p>{isGuest ? "You're browsing as a guest — sign in for wallet & card access." : `Student ID: ${user?.studentId}`}</p>
          </div>
          {isGuest && (
            <button className="btn btn-primary btn-sm" onClick={() => navigate("/login")}>
              Sign in for full access
            </button>
          )}
        </div>

        <form className="dash-search" onSubmit={handleSearch}>
          <input
            className="field"
            placeholder="Search services, locations, events ..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <button type="submit" className="btn btn-primary">Search</button>
        </form>

        <h3 className="section-title">Quick Actions</h3>
        <div className="quick-actions-grid">
          {QUICK_ACTIONS.map((qa) => (
            <button key={qa.to} className="quick-action-card" onClick={() => navigate(qa.to)}>
              <div className="quick-action-visual" style={{ fontSize: "2.2rem" }}>{qa.icon}</div>
              <div className="quick-action-label">{qa.label}</div>
            </button>
          ))}
        </div>

        <div className="dash-lower">
          <MiniCalendar selectedDate={selectedDate} onSelectDate={setSelectedDate} />

          <div className="schedule-card">
            <h3 className="section-title">Today's Schedule</h3>
            {TODAY_SCHEDULE.length === 0 ? (
              <p className="schedule-empty">Nothing scheduled today.</p>
            ) : (
              TODAY_SCHEDULE.map((item, i) => (
                <div className="schedule-item" key={i}>
                  <span className="schedule-time">{item.time}</span>
                  <span className="schedule-title">{item.title}</span>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="announcements-section">
          <h3 className="section-title">Announcements</h3>
          {ANNOUNCEMENTS.map((a, i) => (
            <div className="announcement-item" key={i}>
              <div className="announcement-icon">🔔</div>
              <div>
                <div className="announcement-title">{a.title}</div>
                <div className="announcement-date">{a.date}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
